class Solution {
public:
    vector<string> expand(string s) {
        vector<string> result(1, "");
        for (int i = 0; i < static_cast<int>(s.size());) {
            vector<char> options;
            if (s[i] == '{') {
                ++i;
                while (s[i] != '}') {
                    if (s[i] != ',') {
                        options.push_back(s[i]);
                    }
                    ++i;
                }
                ++i;
            } else {
                options.push_back(s[i++]);
            }
            sort(options.begin(), options.end());
            vector<string> next;
            for (const string& prefix : result) {
                for (char c : options) {
                    next.push_back(prefix + c);
                }
            }
            result.swap(next);
        }
        sort(result.begin(), result.end());
        return result;
    }
};
